import Foundation

public enum ClipboardRules {
    /// Pasteboard markers that mean "do not keep this" (password managers and transient data).
    public static let privateTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "com.typeit4me.clipping",
        "de.petermaurer.TransientPasteboardType",
        "Pasteboard generator type",
    ]

    public static func isRecordable(types: [String]) -> Bool {
        !types.contains(where: privateTypes.contains)
    }

    /// One readable line for a card: collapse whitespace, cap the length.
    public static func preview(_ text: String, limit: Int = 180) -> String {
        let collapsed = text
            .split(whereSeparator: { $0.isWhitespace })
            .joined(separator: " ")
        guard collapsed.count > limit else { return collapsed }
        return String(collapsed.prefix(limit)) + "…"
    }

    public static let capacity = 20
    public static let maximumCharacters = 20_000
}
